"""Explain writer transition and waiter handoff with everyday examples."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1425': ('도서관 책장을 옮기려면 먼저 새 입장을 막고, 안에서 책을 읽던 사람도 모두 나올 때까지 기다려야 합니다. 문을 닫았다고 방이 곧바로 비지는 않습니다.', '쓰기 잠금이 새 읽기를 막은 뒤 기존 읽기가 끝나기를 기다리는 이유를 배웁니다.', '독자 두 명 → 새 입장 차단 → 한 명 퇴장, 남은 수 1 → 마지막 퇴장, 남은 수 0 → 쓰기 시작을 그리세요.', ['reader는 자료를 읽는 작업, writer는 자료를 바꾸는 작업입니다. 함께 읽는 것은 허용하지만, 자료를 고치는 동안 누군가 중간 상태를 읽으면 곤란합니다. 그래서 writer는 독점할 차례를 얻어야 합니다.', 'percpu_down_write는 쓰기 차례를 얻을 때까지 기다릴 수 있는 함수입니다. might_sleep는 기다릴 수 있는 문맥인지 점검하는 장치입니다. rwsem_acquire는 잠금 검사 도구에 알리는 기록이며, 이것만으로 실제 출입이 막히지는 않습니다.', 'rcu_sync_enter는 reader가 빠른 길 대신 차단 표시를 확인하는 느린 길을 이용하도록 전환을 조정합니다. RCU는 여러 CPU에서 진행 중인 접근과 전환 시점을 맞추는 데 쓰이는 기술입니다. 여기서는 빠른 길을 쓰던 읽기와의 전환도 고려해야 합니다.', '그다음 __percpu_down_write_trylock으로 block이라는 차단 표시를 차지하려 합니다. 다른 writer가 이미 차지했다면 percpu_rwsem_wait의 reader 인자에 false를 주어 쓰기 대기자로 기다립니다. false는 쓰기를 취소한다는 뜻이 아닙니다.', 'block을 얻었어도 먼저 들어온 reader가 남아 있을 수 있습니다. rcuwait_wait_event는 readers_active_check가 참이 되기를 기다립니다. CPU별 출입 기록의 합이 0이 되고 필요한 접근 순서도 맞아야 그 검사가 참이 됩니다.', '예를 들어 차단 직후 두 명이 읽고 있다면 합계는 2입니다. 한 명이 끝나 1이 되어도 쓰기를 시작하지 않습니다. 마지막 한 명이 끝나 0을 확인한 뒤 이 함수가 돌아오면 호출자는 보호할 자료를 고칩니다. 마친 뒤에는 percpu_up_write로 반납합니다.'], [('새 입장을 막는 block을 얻었습니다. 그다음 무엇을 기다릴까요?', ['기다릴 필요 없이 바로 자료를 고쳐요', '이미 읽던 작업이 모두 끝나기를 기다려요'], '이미 안에 있던 독자는 문을 닫아도 사라지지 않습니다. 남은 읽기 수가 0인지 확인해야 고치는 중간 모습을 읽는 일이 없으므로 첫 선택지는 잘못입니다.'), ('reader가 차단 표시를 확인하는 느린 길을 쓰도록 전환하는 호출은?', ['rcu_sync_enter예요', 'CPU별 기록 배열을 해제하는 free_percpu예요'], 'rcu_sync_enter가 읽기 경로의 전환을 조정합니다. free_percpu는 메모리를 반납하는 별도 작업이므로, 사용 중인 카운터를 없애는 것으로 잠금을 얻을 수 없습니다.')]), 'os1426': ('칠판을 다 고친 선생님이 문을 열어 줍니다. 아이들이 들어와도 지워지기 전 글씨가 아니라 새 글씨를 읽도록 전달 순서를 맞춰야 합니다.', '쓰기 종료 표시와 빠른 읽기 경로의 복귀가 서로 다른 단계임을 이해합니다.', '자료 수정 → release 방식으로 block=0 → 기다리던 작업 깨우기 → RCU-sync 전환 종료 요청을 적으세요. block=0 옆에 빠른 길 즉시 복귀 아님이라고 쓰세요.', ['percpu_up_write는 쓰기 작업을 마친 뒤 권한을 반납하는 함수입니다. 맨 앞 rwsem_release는 잠금 검사 도구에 반납을 알립니다. 실제 차단 값은 뒤의 atomic_set_release에서 바뀝니다.', 'atomic_set_release(&sem->block,0)는 block을 0으로 바꿉니다. release는 앞서 한 자료 변경이 종료 표시보다 뒤늦은 일처럼 전달되지 않도록 순서를 맞추는 약속입니다. 단순히 숫자만 지우는 것보다 강한 의미가 있습니다.', '느린 읽기 길에는 acquire 방식으로 block을 읽는 부분이 있습니다. acquire는 이 표시를 확인한 뒤의 접근을 앞질러 하지 않도록 맞추는 짝입니다. 이 둘이 연결되어 독자는 writer가 완료한 자료와 일관된 순서로 접근합니다.', '문을 열자마자 모든 reader를 빠른 길로 보내면 이 acquire 확인을 건너뛰어 앞선 쓰기 결과를 제대로 이어받지 못할 수 있습니다. 그래서 block=0이 된 것과 빠른 읽기 경로가 다시 허용되는 것은 같은 순간이 아닙니다.', '__wake_up은 대기열에서 기다리던 읽기·쓰기 작업이 진행할 기회를 줍니다. 여기서 인자 1이 있다고 항상 reader 한 명만 깨운다는 뜻은 아닙니다. 다음 수업의 전용 깨우기 함수가 여러 reader를 이어서 처리할 수 있습니다.', '마지막 rcu_sync_exit는 읽기 경로 전환의 종료를 요청합니다. 원문은 빠른 길 복귀까지 적어도 한 번의 RCU-sched 유예 기간이 필요하다고 설명합니다. 유예 기간은 관련된 이전 실행들이 지나갔는지 기다리는 구간이지 정해진 몇 초가 아닙니다. 다른 writer가 전환을 유지하면 복귀도 더 늦어질 수 있습니다.'], [('block을 0으로 바꾼 직후 빠른 읽기 길을 바로 열지 않는 이유는?', ['모든 CPU의 전원을 꺼야 해서요', '독자가 앞선 쓰기 결과를 올바른 순서로 보게 하려고요'], '느린 길의 acquire 확인과 쓰기 종료의 release가 이어지도록 합니다. 전원을 끄는 절차가 아니며, 잠깐 더 느린 길을 쓰는 것은 자료 접근 순서를 위한 것입니다.'), ('쓰기 종료 때 block을 0으로 바꾸는 방식은?', ['앞선 변경의 순서를 지키는 release 방식이에요', '앞선 변경 순서는 전혀 고려하지 않아요'], '코드의 atomic_set_release라는 이름에 release가 있습니다. 자료를 고친 일과 끝났다는 표시의 순서가 필요하므로 숫자 0만 저장하면 무조건 충분하다는 설명은 틀립니다.')]), 'os1427': ('줄을 서려는 순간 안내원이 빈 줄만 보고 지나가면, 나는 줄에 섰는데도 불러 주는 사람이 없어질 수 있습니다. 자리 확인과 줄 등록을 한 묶음으로 처리해야 합니다.', '대기 등록과 완료 표시 확인으로 깨우기 신호를 놓치지 않는 방법을 배웁니다.', '대기열 잠금 → 획득 재시도 → 실패하면 줄 끝 등록 → 잠금 해제를 그리세요. 별도로 대기 상태 설정 → private 확인 → 미완료이면 잠들기를 적으세요.', ['percpu_rwsem_wait는 바로 들어가지 못한 작업이 차례를 기다리는 함수입니다. 대기열은 기다리는 작업들의 명단입니다. DEFINE_WAIT_FUNC는 자신의 대기 항목과, 차례가 왔을 때 실행할 함수를 준비합니다.', 'waiters.lock을 잡은 상태에서 잠금 획득을 다시 시도합니다. 지금 성공하면 줄에 설 이유가 없으므로 wait가 false가 됩니다. 실패하면 같은 대기열 잠금을 잡은 채 줄 끝에 항목을 넣고 나서 잠금을 풉니다.', '왜 같은 잠금 안에서 할까요? 실패 확인과 등록 사이로 깨우기 작업이 들어와 빈 줄을 보고 끝내지 못하게 하기 위해서입니다. 깨우는 쪽도 대기열 잠금을 이용하므로 등록된 항목을 놓치지 않도록 순서를 맞춥니다.', '등록하는 항목에는 EXCLUSIVE 표시와 reader이면 CUSTOM 표시를 붙입니다. 이 이름들은 코드의 약속입니다. 특히 여기서는 EXCLUSIVE가 붙었다고 reader를 항상 한 명만 깨우는 것은 아닙니다. 깨우기 함수가 반환하는 수도 함께 봐야 합니다.', '줄에 섰다면 먼저 자기 상태를 TASK_UNINTERRUPTIBLE, 즉 이 대기에서 잠들 수 있는 상태로 놓고 private를 acquire 방식으로 확인합니다. private가 NULL이면 깨우는 쪽에서 권한을 확보해 넘겼다는 완료 표시라 반복을 끝냅니다. 여기의 NULL은 잠금 객체를 지웠다는 뜻이 아닙니다.', '아직 완료 표시가 없으면 schedule로 다른 작업에 CPU를 양보합니다. 상태를 먼저 정하고 표시를 확인해야 확인 직후 들어온 깨우기를 놓치고 계속 자는 일을 막을 수 있습니다. 반복이 끝나면 TASK_RUNNING으로 돌립니다. 처음 재시도에서 성공했다면 이 잠들기 반복 자체를 건너뜁니다.'], [('대기 중 private가 NULL로 바뀐 것을 확인했습니다. 무슨 신호일까요?', ['잠금 객체가 삭제됐다는 신호예요', '깨우는 쪽이 권한을 얻어 넘겼다는 완료 신호예요'], '이 함수에서는 private를 완료 표시로도 사용합니다. 깨우는 함수가 획득에 성공한 뒤 NULL을 기록하므로 기다림을 끝냅니다. 메모리를 해제했다는 뜻으로 읽으면 안 됩니다.'), ('획득 재시도와 실패 후 줄 등록을 같은 대기열 잠금 안에서 하는 이유는?', ['그 사이의 깨우기가 내 등록을 놓치지 않게 하려고요', '모든 기다림을 무조건 없애려고요'], '실패했지만 아직 명단에 없는 틈을 없애는 것입니다. 다른 작업이 권한을 가진 동안 실제 기다림은 여전히 필요하므로 두 번째 설명은 맞지 않습니다.')]), 'os1428': ('안내원이 줄 앞의 독자들은 함께 들여보내되 책장을 고칠 사람을 선택하면 그 뒤의 입장은 멈춥니다. 깨웠는지와 다음 사람까지 살펴볼지는 서로 다른 판단입니다.', '깨우기 함수의 반환값으로 reader 묶음과 writer 한 명을 처리하는 원리를 배웁니다.', '줄에 R1,R2,W1,R3를 적으세요. 획득이 차례로 성공한다고 가정하면 R1과 R2는 깨우고 계속, W1은 깨우고 멈춤입니다. W1은 실제 쓰기 전에 앞선 독자들의 종료도 기다립니다.', ['percpu_rwsem_wake_function은 대기 항목 하나를 처리하는 함수입니다. WQ_FLAG_CUSTOM 표시가 있으면 reader로 분류합니다. 먼저 그 작업을 대신하여 읽기 또는 쓰기 잠금 획득을 시도합니다. 깨우기 전에 실제 권한을 확보하려는 것입니다.', '시도가 실패하면 아무도 깨우지 않고 1을 반환합니다. 일반 규칙에서 양수는 깨웠다는 의미로 쓰이지만 이 전용 함수는 1을 대기열 훑기를 멈추는 데도 이용합니다. 호출자가 둔 EXCLUSIVE 처리 한도 1을 소모하기 때문입니다.', '성공하면 private에 담긴 task_struct를 get_task_struct로 붙잡습니다. task_struct는 실행할 작업의 정보를 담은 구조체입니다. 붙잡는다는 말은 참조 수를 늘려 이 함수가 사용하는 동안 그 정보가 없어지지 않게 한다는 뜻입니다.', '이어서 대기열에서 항목을 빼고, private에 release 방식으로 NULL을 씁니다. 기다리던 쪽이 acquire로 이 값을 보면 획득 완료를 압니다. 그쪽은 이제 자기 대기 항목의 사용을 끝낼 수 있으므로, 깨우는 쪽은 미리 저장해 붙잡은 작업 포인터 p를 씁니다.', 'wake_up_process(p)로 작업을 깨운 뒤 put_task_struct(p)로 임시 참조를 반납합니다. 성공한 reader는 !reader가 0이라 다음 항목도 살펴보게 합니다. 이미 깨웠는데도 반환값이 0인 점에 주의하세요. 성공한 writer는 1을 반환해 한도를 채우고 멈춥니다.', '그래서 앞의 reader 여러 명을 처리하다 writer 한 명을 선택하거나 획득 실패를 만나면 멈춥니다. 선택된 writer도 기존 reader가 끝나기 전에는 자료를 고치지 않습니다. FIFO는 먼저 줄 선 순서를 따르려는 방식이지만, 원문에는 동시에 새로 시도하는 writer가 차단을 먼저 차지할 수 있다고 적혀 있어 절대적인 순서 보장은 아닙니다.'], [('reader를 깨운 뒤 이 함수가 0을 반환합니다. 무슨 뜻일까요?', ['0이므로 실제로는 아무도 깨우지 않았어요', 'reader는 깨웠고 다음 대기 항목도 살펴보게 해요'], '이 전용 함수는 wake_up_process를 호출한 뒤에도 reader이면 0을 반환합니다. 다음 reader도 이어서 처리하려는 약속이므로 0을 언제나 깨우지 않았다고 해석하면 틀립니다.'), ('writer 획득에 성공해 깨운 뒤에는 무엇을 반환할까요?', ['1을 반환해 이번 대기열 훑기를 멈추게 해요', '0을 반환해 뒤의 모두에게 즉시 쓰기 권한을 줘요'], 'writer일 때 reader는 false이므로 !reader는 1입니다. 한도 1이 채워져 멈추며, writer 여러 명에게 동시에 쓰기 권한을 주는 것은 잠금의 목적에도 맞지 않습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_352.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
